            if (cyc > 37) begin nc = nc + 1; if (u_lp.u_recip.v !== u_flat.u_recip.v) begin bad = bad + 1; if (bad <= 5) $display("LP_MISMATCH child=u_recip.v cycle=%0d flat=%h landed=%h", cyc, u_flat.u_recip.v, u_lp.u_recip.v); end end
            if (cyc > 37) begin nc = nc + 1; if (u_lp.u_recip.vo !== u_flat.u_recip.vo) begin bad = bad + 1; if (bad <= 5) $display("LP_MISMATCH child=u_recip.vo cycle=%0d flat=%h landed=%h", cyc, u_flat.u_recip.vo, u_lp.u_recip.vo); end end
            if (cyc > 37) begin nc = nc + 1; if (u_lp.u_recip.x !== u_flat.u_recip.x) begin bad = bad + 1; if (bad <= 5) $display("LP_MISMATCH child=u_recip.x cycle=%0d flat=%h landed=%h", cyc, u_flat.u_recip.x, u_lp.u_recip.x); end end
            if (cyc > 37) begin nc = nc + 1; if (u_lp.u_recip.y !== u_flat.u_recip.y) begin bad = bad + 1; if (bad <= 5) $display("LP_MISMATCH child=u_recip.y cycle=%0d flat=%h landed=%h", cyc, u_flat.u_recip.y, u_lp.u_recip.y); end end
        end
        if (bad == 0 && nc > 0) $display("LP_LOCKSTEP PASS MUT=%0d compared=%0d cycles=9000 warm=37", MUT, nc);
        else $display("LP_LOCKSTEP FAIL MUT=%0d mismatches=%0d of %0d", MUT, bad, nc);
        $finish;
    end
